class AuthVerifier:
    _basic_prefix = "Basic "
    _bearer_prefix = "Bearer "

    def __init__(self, request: Request):
        self.auth_info = mlrun.api.schemas.AuthInfo()

        self._authenticate_request(request)

    def _authenticate_request(self, request: Request):
        header = request.headers.get("Authorization", "")
        if self._basic_auth_required():
            if not header.startswith(self._basic_prefix):
                log_and_raise(
                    HTTPStatus.UNAUTHORIZED.value, reason="Missing basic auth header"
                )
            username, password = self._parse_basic_auth(header)
            if (
                username != config.httpdb.authentication.basic.username
                or password != config.httpdb.authentication.basic.password
            ):
                log_and_raise(
                    HTTPStatus.UNAUTHORIZED.value,
                    reason="Username or password did not match",
                )
            self.auth_info.username = username
            self.auth_info.password = password
        elif self._bearer_auth_required():
            if not header.startswith(self._bearer_prefix):
                log_and_raise(
                    HTTPStatus.UNAUTHORIZED.value, reason="Missing bearer auth header"
                )
            token = header[len(self._bearer_prefix) :]
            if token != config.httpdb.authentication.bearer.token:
                log_and_raise(
                    HTTPStatus.UNAUTHORIZED.value, reason="Token did not match"
                )
            self.auth_info.token = token
        elif self._iguazio_auth_required():
            iguazio_client = mlrun.api.utils.clients.iguazio.Client()
            (
                self.auth_info.username,
                self.auth_info.session,
                self.auth_info.user_id,
                self.auth_info.user_group_ids,
                planes,
            ) = iguazio_client.verify_request_session(request)
            if "x-data-session-override" in request.headers:
                self.auth_info.data_session = request.headers["x-data-session-override"]
            elif "data" in planes:
                self.auth_info.data_session = self.auth_info.session
        projects_role_header = request.headers.get(
            mlrun.api.schemas.HeaderNames.projects_role
        )
        self.auth_info.projects_role = (
            mlrun.api.schemas.ProjectsRole(projects_role_header)
            if projects_role_header
            else None
        )
        # In Iguazio 3.0 we're running with auth mode none cause auth is done by the ingress, in that auth mode sessions
        # needed for data operations were passed through this header, keep reading it to be backwards compatible
        if not self.auth_info.data_session and "X-V3io-Session-Key" in request.headers:
            self.auth_info.data_session = request.headers["X-V3io-Session-Key"]

    @staticmethod
    def _basic_auth_required():
        return config.httpdb.authentication.mode == "basic" and (
            config.httpdb.authentication.basic.username
            or config.httpdb.authentication.basic.password
        )

    @staticmethod
    def _bearer_auth_required():
        return (
            config.httpdb.authentication.mode == "bearer"
            and config.httpdb.authentication.bearer.token
        )

    @staticmethod
    def _iguazio_auth_required():
        return config.httpdb.authentication.mode == "iguazio"

    @staticmethod
    def _parse_basic_auth(header):
        """
        parse_basic_auth('Basic YnVnczpidW5ueQ==')
        ['bugs', 'bunny']
        """
        b64value = header[len(AuthVerifier._basic_prefix) :]
        value = b64decode(b64value).decode()
        return value.split(":", 1)

class Pipelines(metaclass=mlrun.utils.singleton.Singleton,):
    def list_pipelines(
        self,
        project: str,
        namespace: str = mlrun.mlconf.namespace,
        sort_by: str = "",
        page_token: str = "",
        filter_: str = "",
        format_: mlrun.api.schemas.PipelinesFormat = mlrun.api.schemas.PipelinesFormat.metadata_only,
        page_size: typing.Optional[int] = None,
    ) -> typing.Tuple[int, typing.Optional[int], typing.List[dict]]:
        if project != "*" and (page_token or page_size or sort_by or filter_):
            raise mlrun.errors.MLRunInvalidArgumentError(
                "Filtering by project can not be used together with pagination, sorting, or custom filter"
            )
        kfp_client = kfp.Client(namespace=namespace)
        if project != "*":
            run_dicts = []
            while page_token is not None:
                response = kfp_client._run_api.list_runs(
                    page_token=page_token,
                    page_size=mlrun.api.schemas.PipelinesPagination.max_page_size,
                )
                run_dicts.extend([run.to_dict() for run in response.runs or []])
                page_token = response.next_page_token
            project_runs = []
            for run_dict in run_dicts:
                run_project = self.resolve_project_from_pipeline(run_dict)
                if run_project == project:
                    project_runs.append(run_dict)
            runs = project_runs
            total_size = len(project_runs)
            next_page_token = None
        else:
            response = kfp_client._run_api.list_runs(
                page_token=page_token,
                page_size=page_size
                or mlrun.api.schemas.PipelinesPagination.default_page_size,
                sort_by=sort_by,
                filter=filter_,
            )
            runs = [run.to_dict() for run in response.runs or []]
            total_size = response.total_size
            next_page_token = response.next_page_token
        runs = self._format_runs(runs, format_)

        return total_size, next_page_token, runs

    def get_pipeline(
        self,
        db_session: sqlalchemy.orm.Session,
        run_id: str,
        project: typing.Optional[str] = None,
        namespace: str = mlrun.mlconf.namespace,
        format_: mlrun.api.schemas.PipelinesFormat = mlrun.api.schemas.PipelinesFormat.summary,
    ):
        kfp_client = kfp.Client(namespace=namespace)
        try:
            run = kfp_client.get_run(run_id)
            if run:
                run = run.to_dict()
                if format_ == mlrun.api.schemas.PipelinesFormat.summary:
                    run = mlrun.kfpops.format_summary_from_kfp_run(
                        run, project=project, session=db_session
                    )
                elif format_ == mlrun.api.schemas.PipelinesFormat.full:
                    pass
                else:
                    raise NotImplementedError(
                        f"Provided format is not supported. format={format_}"
                    )

        except Exception as exc:
            mlrun.api.api.utils.log_and_raise(
                http.HTTPStatus.INTERNAL_SERVER_ERROR.value,
                reason=f"get kfp error: {exc}",
            )

        return run

    def create_pipeline(
        self,
        experiment_name: str,
        run_name: str,
        content_type: str,
        data: bytes,
        arguments: dict = None,
        namespace: str = mlrun.mlconf.namespace,
    ):
        if arguments is None:
            arguments = {}
        if "/yaml" in content_type:
            content_type = ".yaml"
        elif " /zip" in content_type:
            content_type = ".zip"
        else:
            mlrun.api.api.utils.log_and_raise(
                http.HTTPStatus.BAD_REQUEST.value,
                reason=f"unsupported pipeline type {content_type}",
            )

        logger.debug("Writing pipeline to temp file", content_type=content_type)
        print(str(data))

        pipeline_file = tempfile.NamedTemporaryFile(suffix=content_type)
        with open(pipeline_file.name, "wb") as fp:
            fp.write(data)

        logger.info(
            "Creating pipeline",
            experiment_name=experiment_name,
            run_name=run_name,
            arguments=arguments,
        )

        try:
            kfp_client = kfp.Client(namespace=namespace)
            experiment = kfp_client.create_experiment(name=experiment_name)
            run = kfp_client.run_pipeline(
                experiment.id, run_name, pipeline_file.name, params=arguments
            )
        except Exception as exc:
            logger.warning(
                "Failed creating pipeline",
                traceback=traceback.format_exc(),
                exc=str(exc),
            )
            raise mlrun.errors.MLRunBadRequestError(f"Failed creating pipeline: {exc}")
        finally:
            pipeline_file.close()

        return run

    def _format_runs(
        self,
        runs: typing.List[dict],
        format_: mlrun.api.schemas.PipelinesFormat = mlrun.api.schemas.PipelinesFormat.metadata_only,
    ) -> typing.List[dict]:
        for run in runs:
            run["project"] = self.resolve_project_from_pipeline(run)
        if format_ == mlrun.api.schemas.PipelinesFormat.full:
            return runs
        elif format_ == mlrun.api.schemas.PipelinesFormat.metadata_only:
            formatted_runs = []
            for run in runs:
                formatted_runs.append(
                    {
                        k: str(v)
                        for k, v in run.items()
                        if k
                        in [
                            "id",
                            "name",
                            "project",
                            "status",
                            "error",
                            "created_at",
                            "scheduled_at",
                            "finished_at",
                            "description",
                        ]
                    }
                )
            return formatted_runs
        elif format_ == mlrun.api.schemas.PipelinesFormat.name_only:
            formatted_runs = []
            for run in runs:
                formatted_runs.append(run.get("name"))
            return formatted_runs
        else:
            raise NotImplementedError(
                f"Provided format is not supported. format={format_}"
            )

    def _resolve_project_from_command(
        self,
        command: typing.List[str],
        hyphen_p_is_also_project: bool,
        has_func_url_flags: bool,
        has_runtime_flags: bool,
    ):
        # project has precedence over function url so search for it first
        for index, argument in enumerate(command):
            if (
                (argument == "-p" and hyphen_p_is_also_project)
                or argument == "--project"
            ) and index + 1 < len(command):
                return command[index + 1]
        if has_func_url_flags:
            for index, argument in enumerate(command):
                if (argument == "-f" or argument == "--func-url") and index + 1 < len(
                    command
                ):
                    function_url = command[index + 1]
                    if function_url.startswith("db://"):
                        (
                            project,
                            _,
                            _,
                            _,
                        ) = mlrun.utils.helpers.parse_versioned_object_uri(
                            function_url[len("db://") :]
                        )
                        if project:
                            return project
        if has_runtime_flags:
            for index, argument in enumerate(command):
                if (argument == "-r" or argument == "--runtime") and index + 1 < len(
                    command
                ):
                    runtime = command[index + 1]
                    try:
                        parsed_runtime = ast.literal_eval(runtime)
                    except Exception as exc:
                        logger.warning(
                            "Failed parsing runtime. Skipping", runtime=runtime, exc=exc
                        )
                    else:
                        if isinstance(parsed_runtime, dict):
                            project = parsed_runtime.get("metadata", {}).get("project")
                            if project:
                                return project

        return None

    def resolve_project_from_pipeline(self, pipeline):
        workflow_manifest = json.loads(
            pipeline.get("pipeline_spec", {}).get("workflow_manifest") or "{}"
        )
        return self.resolve_project_from_workflow_manifest(workflow_manifest)

    def resolve_project_from_workflow_manifest(self, workflow_manifest):
        templates = workflow_manifest.get("spec", {}).get("templates", [])
        for template in templates:
            project_from_annotation = (
                template.get("metadata", {})
                .get("annotations", {})
                .get(mlrun.kfpops.project_annotation)
            )
            if project_from_annotation:
                return project_from_annotation
            command = template.get("container", {}).get("command", [])
            action = None
            for index, argument in enumerate(command):
                if argument == "mlrun" and index + 1 < len(command):
                    action = command[index + 1]
                    break
            if action:
                if action == "deploy":
                    project = self._resolve_project_from_command(
                        command,
                        hyphen_p_is_also_project=True,
                        has_func_url_flags=True,
                        has_runtime_flags=False,
                    )
                    if project:
                        return project
                elif action == "run":
                    project = self._resolve_project_from_command(
                        command,
                        hyphen_p_is_also_project=False,
                        has_func_url_flags=True,
                        has_runtime_flags=True,
                    )
                    if project:
                        return project
                elif action == "build":
                    project = self._resolve_project_from_command(
                        command,
                        hyphen_p_is_also_project=False,
                        has_func_url_flags=False,
                        has_runtime_flags=True,
                    )
                    if project:
                        return project
                else:
                    raise NotImplementedError(f"Unknown action: {action}")

        return mlrun.mlconf.default_project
